// Test script for complete composite FK workflow
// This simulates the complete flow from SQL to DBML to ER visualization

// Test DBML that would be generated by the backend
const testDbml = `Project Test Schema {
  database_type: 'PostgreSQL'
  Note: 'Generated from SQL Schema via pgsql-ast-parser'
}

Table users {
  id int [pk, not null]
  name varchar [not null]
}

Table orders {
  order_id int [pk, not null]
  customer_id int [pk, not null]
  order_date date
}

Table order_items {
  item_id int [pk, not null]
  order_id int
  customer_id int
  product_name varchar
  quantity int
  created_by int [ref: > users.id]
}

Ref: (order_items.order_id, order_items.customer_id) > (orders.order_id, orders.customer_id)
Ref: order_items.created_by > users.id
`;

// Frontend parsing functions (copied from the component)
function parseDbmlTables(dbmlCode) {
  const tables = [];
  const tableRegex = /Table\s+(\w+)\s*\{([^}]+)\}/g;
  let match;
  
  while ((match = tableRegex.exec(dbmlCode)) !== null) {
    const tableName = match[1];
    const tableContent = match[2];
    
    const columns = parseTableColumns(tableContent);
    tables.push({ name: tableName, columns });
  }
  
  return tables;
}

function parseTableColumns(tableContent) {
  const columns = [];
  const lines = tableContent.split('\n').map(line => line.trim()).filter(line => line);
  
  lines.forEach(line => {
    if (line.includes('//') || line.includes('/*')) return; // Skip comments
    
    const parts = line.split(/\s+/);
    if (parts.length < 2) return;
    
    const name = parts[0];
    const type = parts[1];
    
    const isPrimaryKey = /\[.*\bpk\b.*\]/i.test(line) || /\[.*primary key.*\]/i.test(line);
    const isUnique = /\[.*\buq\b.*\]/i.test(line) || /\[.*unique.*\]/i.test(line);
    
    const refMatch = line.match(/ref:\s*>\s*(\w+)\.(\w+)/i);
    const isForeignKey = !!refMatch || /\[.*foreign key.*\]/i.test(line);
    
    let references = undefined;
    if (refMatch) {
      references = {
        table: refMatch[1],
        column: refMatch[2]
      };
    }
    
    columns.push({ name, type, isPrimaryKey, isForeignKey, isUnique, references });
  });
  
  return columns;
}

function parseDbmlRelationships(dbmlCode) {
  const relationships = [];
  
  // Pattern for single column relationships: table.column > table.column
  const singleRefRegex = /(\w+)\.(\w+)\s*>\s*(\w+)\.(\w+)/g;
  
  // Pattern for composite relationships: (table.col1, table.col2) > (table.col1, table.col2)
  const compositeRefRegex = /\(([^)]+)\)\s*>\s*\(([^)]+)\)/g;
  
  let match;
  
  // Parse single column relationships
  while ((match = singleRefRegex.exec(dbmlCode)) !== null) {
    relationships.push({
      fromTable: match[1],
      fromColumn: match[2],
      toTable: match[3],
      toColumn: match[4]
    });
  }
  
  // Parse composite relationships
  while ((match = compositeRefRegex.exec(dbmlCode)) !== null) {
    const fromPart = match[1];
    const toPart = match[2];
    
    // Parse source columns from "table.col1, table.col2" format
    const fromColumns = parseCompositeColumns(fromPart);
    const toColumns = parseCompositeColumns(toPart);
    
    if (fromColumns.length > 0 && toColumns.length > 0 && fromColumns.length === toColumns.length) {
      relationships.push({
        fromTable: fromColumns[0].table,
        fromColumn: fromColumns.map(c => c.column),
        toTable: toColumns[0].table,
        toColumn: toColumns.map(c => c.column)
      });
    }
  }
  
  return relationships;
}

function parseCompositeColumns(columnsPart) {
  const columns = [];
  const parts = columnsPart.split(',').map(p => p.trim());
  
  parts.forEach(part => {
    const match = part.match(/(\w+)\.(\w+)/);
    if (match) {
      columns.push({
        table: match[1],
        column: match[2]
      });
    }
  });
  
  return columns;
}

// Run the test
console.log('🔬 === COMPLETE COMPOSITE FK FRONTEND TEST ===');

console.log('\n📋 Test DBML:');
console.log(testDbml);

console.log('\n🔍 Parsing Results:');

// Parse tables
const tables = parseDbmlTables(testDbml);
console.log('Tables found:', tables.length);
tables.forEach((table, i) => {
  console.log(`  Table ${i+1}: ${table.name} (${table.columns.length} columns)`);
  table.columns.forEach(col => {
    const flags = [];
    if (col.isPrimaryKey) flags.push('PK');
    if (col.isForeignKey) flags.push('FK');
    if (col.isUnique) flags.push('UQ');
    const flagsStr = flags.length > 0 ? ` [${flags.join(', ')}]` : '';
    const refStr = col.references ? ` -> ${col.references.table}.${col.references.column}` : '';
    console.log(`    - ${col.name} ${col.type}${flagsStr}${refStr}`);
  });
});

// Parse relationships
const relationships = parseDbmlRelationships(testDbml);
console.log('\nRelationships found:', relationships.length);
relationships.forEach((rel, i) => {
  const fromColumns = Array.isArray(rel.fromColumn) ? rel.fromColumn.join(', ') : rel.fromColumn;
  const toColumns = Array.isArray(rel.toColumn) ? rel.toColumn.join(', ') : rel.toColumn;
  const isComposite = Array.isArray(rel.fromColumn) && rel.fromColumn.length > 1;
  
  console.log(`  Relationship ${i+1}: ${rel.fromTable}.[${fromColumns}] -> ${rel.toTable}.[${toColumns}] (${isComposite ? 'COMPOSITE' : 'SINGLE'})`);
});

console.log('\n🎯 Validation Results:');

// Check for expected relationships
const compositeRel = relationships.find(r => Array.isArray(r.fromColumn) && r.fromColumn.length === 2);
const singleRel = relationships.find(r => !Array.isArray(r.fromColumn));

console.log('✅ Composite FK found:', compositeRel ? 'YES' : 'NO');
if (compositeRel) {
  console.log(`   ${compositeRel.fromTable}.[${compositeRel.fromColumn.join(', ')}] -> ${compositeRel.toTable}.[${compositeRel.toColumn.join(', ')}]`);
}

console.log('✅ Single FK found:', singleRel ? 'YES' : 'NO');
if (singleRel) {
  console.log(`   ${singleRel.fromTable}.${singleRel.fromColumn} -> ${singleRel.toTable}.${singleRel.toColumn}`);
}

// Test the HTML generation (simplified)
console.log('\n🎨 HTML Generation Test:');
let html = '<div class="relationships-section"><h4>Beziehungen:</h4><ul>';
relationships.forEach((rel) => {
  const fromColumns = Array.isArray(rel.fromColumn) ? rel.fromColumn.join(', ') : rel.fromColumn;
  const toColumns = Array.isArray(rel.toColumn) ? rel.toColumn.join(', ') : rel.toColumn;
  const isComposite = Array.isArray(rel.fromColumn) && rel.fromColumn.length > 1;
  
  html += `<li class="${isComposite ? 'composite-fk' : 'single-fk'}">
    ${rel.fromTable}.[${fromColumns}] → ${rel.toTable}.[${toColumns}]
    ${isComposite ? '<span class="composite-badge">Zusammengesetzt</span>' : ''}
  </li>`;
});
html += '</ul></div>';

console.log('Generated HTML:');
console.log(html);

console.log('\n🚀 === FINAL RESULT ===');
if (compositeRel && singleRel && relationships.length === 2) {
  console.log('✅ SUCCESS: Complete composite FK workflow is working correctly!');
  console.log('   - Backend DBML generation: ✅');
  console.log('   - Frontend DBML parsing: ✅');
  console.log('   - Composite FK detection: ✅');
  console.log('   - HTML visualization: ✅');
} else {
  console.log('❌ FAILURE: Something is not working correctly.');
  console.log(`   - Expected: 2 relationships (1 composite, 1 single)`);
  console.log(`   - Found: ${relationships.length} relationships (${relationships.filter(r => Array.isArray(r.fromColumn)).length} composite, ${relationships.filter(r => !Array.isArray(r.fromColumn)).length} single)`);
}
